const FACTORS = ["health", "taste", "price", "speed"];

const FACTOR_LABELS = {
  health: "营养",
  taste: "口味",
  price: "价格",
  speed: "速度"
};

const FACTOR_REASONS = {
  health: "营养负担更轻",
  taste: "口味满足感更高",
  price: "预算余量更充足",
  speed: "送达时间更稳"
};

function clamp(value, min = 0, max = 100) {
  return Math.min(max, Math.max(min, value));
}

function normalizeWeights(weights = {}) {
  const values = FACTORS.map((factor) => Math.max(0, Number(weights[factor]) || 0));
  const total = values.reduce((sum, value) => sum + value, 0);

  if (total === 0) {
    return { health: 25, taste: 25, price: 25, speed: 25 };
  }

  return Object.fromEntries(
    FACTORS.map((factor, index) => [factor, (values[index] / total) * 100])
  );
}

function hardConstraintViolations(item, constraints) {
  const violations = [];
  const exclusions = new Set(constraints.exclusions || []);

  if (item.price > Number(constraints.budget)) {
    violations.push("budget");
  }

  if (item.deliveryMin > Number(constraints.deadline)) {
    violations.push("deadline");
  }

  if ((item.flags || []).some((flag) => exclusions.has(flag))) {
    violations.push("exclusion");
  }

  return violations;
}

function calculateFactorScores(item, constraints) {
  const budget = Math.max(Number(constraints.budget) || 1, 1);
  const deadline = Math.max(Number(constraints.deadline) || 1, 1);

  return {
    health: clamp(item.health),
    taste: clamp(item.taste),
    price: clamp(112 - (item.price / budget) * 62, 35, 100),
    speed: clamp(116 - (item.deliveryMin / deadline) * 72, 35, 100)
  };
}

function buildExplanation(item, factorScores, normalizedWeights) {
  const weightedFactors = FACTORS.map((factor) => ({
    factor,
    contribution: factorScores[factor] * normalizedWeights[factor]
  })).sort((a, b) => b.contribution - a.contribution);

  const weakestFactor = FACTORS.map((factor) => ({ factor, score: factorScores[factor] }))
    .sort((a, b) => a.score - b.score)[0];

  const leadTag = item.tags?.[0] ? `${item.tags[0]}，` : "";
  const reason = `${leadTag}${FACTOR_REASONS[weightedFactors[0].factor]}`;

  let tradeoff = "各项表现比较均衡";
  if (weakestFactor.factor === "health" && weakestFactor.score < 62) {
    tradeoff = "热量和油盐负担偏高，更适合偶尔犒劳";
  } else if (weakestFactor.factor === "taste" && weakestFactor.score < 80) {
    tradeoff = "口味偏清淡，满足感可能不如重口选项";
  } else if (weakestFactor.factor === "price" && weakestFactor.score < 62) {
    tradeoff = "价格接近本餐预算上限";
  } else if (weakestFactor.factor === "speed" && weakestFactor.score < 62) {
    tradeoff = "配送时间接近最晚送达要求";
  }

  return {
    reason,
    tradeoff,
    strongestFactor: weightedFactors[0].factor,
    weakestFactor: weakestFactor.factor
  };
}

function rankMenu(menuItems, constraints, weights, profile = {}) {
  const normalizedWeights = normalizeWeights(weights);
  const cuisineAffinity = profile.cuisineAffinity || {};
  const rejectedDishIds = new Set(profile.rejectedDishIds || []);

  return menuItems
    .filter((item) => hardConstraintViolations(item, constraints).length === 0)
    .map((item) => {
      const factorScores = calculateFactorScores(item, constraints);
      const weightedScore = FACTORS.reduce(
        (sum, factor) => sum + factorScores[factor] * (normalizedWeights[factor] / 100),
        0
      );
      const affinityBoost = clamp(Number(cuisineAffinity[item.cuisine]) || 0, -5, 5);
      const rejectionPenalty = rejectedDishIds.has(item.id) ? 12 : 0;
      const totalScore = clamp(weightedScore + affinityBoost - rejectionPenalty);
      const explanation = buildExplanation(item, factorScores, normalizedWeights);

      return {
        ...item,
        factorScores,
        totalScore: Math.round(totalScore),
        reason: explanation.reason,
        tradeoff: explanation.tradeoff,
        strongestFactor: explanation.strongestFactor,
        weakestFactor: explanation.weakestFactor
      };
    })
    .sort((a, b) => {
      if (b.totalScore !== a.totalScore) return b.totalScore - a.totalScore;
      if (a.price !== b.price) return a.price - b.price;
      return a.deliveryMin - b.deliveryMin;
    });
}

function bestBy(rows, scoreFn) {
  return rows.reduce((best, row) => {
    if (!best || scoreFn(row) > scoreFn(best)) return row;
    return best;
  }, null);
}

function selectTopThree(rankedItems, omittedIds = []) {
  const omitted = new Set(omittedIds);
  const available = rankedItems.filter((item) => !omitted.has(item.id));

  if (available.length === 0) return [];

  const primary = available[0];
  const remainingAfterPrimary = available.filter((item) => item.id !== primary.id);
  const speedChoice = bestBy(
    remainingAfterPrimary.slice(0, 12),
    (item) => item.factorScores.speed * 0.62 + item.totalScore * 0.38
  );
  const remainingAfterSpeed = remainingAfterPrimary.filter((item) => item.id !== speedChoice?.id);
  const healthChoice = bestBy(
    remainingAfterSpeed.slice(0, 12),
    (item) => item.factorScores.health * 0.62 + item.totalScore * 0.38
  );

  return [
    primary ? { ...primary, recommendationLabel: "最合你意" } : null,
    speedChoice ? { ...speedChoice, recommendationLabel: "时间更稳" } : null,
    healthChoice ? { ...healthChoice, recommendationLabel: "营养更优" } : null
  ].filter(Boolean);
}

function recommend(menuItems, constraints, weights, profile = {}, omittedIds = []) {
  const ranked = rankMenu(menuItems, constraints, weights, profile);
  return {
    ranked,
    recommendations: selectTopThree(ranked, omittedIds),
    eligibleCount: ranked.length,
    totalCount: menuItems.length
  };
}

function findReplacement(rankedItems, currentIds, omittedIds = []) {
  const unavailable = new Set([...currentIds, ...omittedIds]);
  return rankedItems.find((item) => !unavailable.has(item.id)) || null;
}

function isEffectiveDecision(item, constraints, elapsedMs) {
  return Boolean(item)
    && elapsedMs <= 60_000
    && hardConstraintViolations(item, constraints).length === 0;
}



